/** 会话记录头（只写用到的字段）。 */
export interface Header { readonly id: string; readonly cwd?: string; readonly [k: string]: unknown }
export interface Snapshot { readonly header: Header; readonly [k: string]: unknown }
export interface Handle { readonly id: string; readonly header: Header; readonly [k: string]: unknown }
type Opts = { readonly signal?: AbortSignal; readonly [k: string]: unknown } | undefined

/** 原版 JSONL 实例的对外方法（与 DSH 的 SessionPersistence 相同）。 */
export interface Backend {
  create(header: Header, options?: Opts): Promise<Handle>
  open(id: string, access: 'read' | 'write', options?: Opts): Promise<Handle>
  flush(): Promise<void>
  stat(id: string, options?: Opts): Promise<Snapshot | undefined>
  list(options?: Opts): Promise<readonly Snapshot[]>
}

export type LogFn = (level: 'info' | 'warn' | 'error', event: string, meta?: Record<string, unknown>) => void

export interface RouterOptions {
  /** 不在案件里的会话的记录根（$DSH_HOME\sessions）。 */
  defaultRoot: string
  /** 不在案件里的会话是否允许新建、续写（N46 用户定 ②：不允许）。 */
  allowOutsideCase: boolean
  /** 刷新案件根名单（问工作台服务）；服务不在时什么也不做。 */
  refresh?: (force?: boolean) => Promise<void>
  /**
   * 名单是否已按服务刷新成功过一次，以及有上限地等第一次刷新（第三轮复核 B-F4）。不给时当作已刷新过。
   * wait 在已刷新过时立刻返回 true；最多等 3 秒，到时还没刷新成功返回 false。
   */
  firstRefresh?: { done(): boolean; wait(): Promise<boolean> }
  /** 单个案件根 list、stat 的上限（毫秒），超时就跳过（第三轮复核 B-F5）。默认 3000。 */
  caseRootTimeoutMs?: number
  log?: LogFn
  /** 内存里这个会话此刻的事件数（DSH 会话的 seq）；接回时核对用，不给时不接回。 */
  liveSeq?: (id: string) => number | undefined
}

/** 案件里存会话记录的子目录（相对案件根）。 */
export const CASE_SESSION_DIR = join('工作区', '会话')
export const OUTSIDE_CASE = '这个文件夹还没有作为案件打开，不能在这里新建对话。请先从首页打开案件。'
/** 名单还没拿到（缓存为空且工作台服务还没起来）时新建的说明（第三轮复核 B-F4）。 */
export const NOT_READY = '工作台服务还没就绪，稍后再试。'

const isNotFound = (error: unknown): boolean => (error as Error)?.name === 'SessionPersistenceNotFoundError'
/** 原版 JSONL 的物理快照才带 sizeBytes；同进程的 pending header 只有内存 revision。 */
const isPersistedSnapshot = (snapshot: Snapshot | undefined): boolean =>
  typeof snapshot?.sizeBytes === 'number' && snapshot.sizeBytes > 0

/** 给一次读取加上限：到时没回来就按"超时"失败（原来那次读取不取消，结果丢掉）。 */
function within<T>(p: Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(Object.assign(new Error('case root timed out'), { code: 'ETIMEDOUT' })), ms)
  })
  return Promise.race([p, timeout]).finally(() => clearTimeout(timer))
}

interface Store { readonly root: string; readonly caseRoot: string | null; readonly backend: Backend; readonly index: number }
/** 交出去的一个案件写句柄：属于哪个实例、真正的句柄是哪个、是否已放下（见 recheck）。 */
interface Writer {
  readonly id: string
  readonly at: Store
  cur: Handle
  detached: boolean
  /** 这个会话的记录已在盘上见过（打开已有会话时即是；新建的要等原版第一次落盘）。见过之后又没了，算位置失效。 */
  seen: boolean
}
/** 原版给会话编号编成目录名的写法（session-persistence-jsonl/src/format.ts 的 encodeSegment）。 */
export const encodeSegment = (raw: string): string => {
  if (raw.length === 0) throw new Error('cannot encode an empty path segment')
  if (raw === '.') return '~002E'
  if (raw === '..') return '~002E~002E'
  let out = ''
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i)
    const ch = String.fromCharCode(code)
    out += ch !== '~' && /^[A-Za-z0-9._-]$/.test(ch) ? ch : '~' + code.toString(16).toUpperCase().padStart(4, '0')
  }
  return out
}
const closeHandle = (h: Handle): Promise<void> => (h.close as () => Promise<void>).call(h)

export class SessionRouter {
  private readonly stores = new Map<string, Store>()
  private readonly owner = new Map<string, Store>()
  /** 成功 create 后尚未确认真正落盘的会话；pending 的 list/open/stat 可见性不算落盘，open 不能重新授予。 */
  private readonly neverPersisted = new Set<string>()
  private readonly defaultStore: Store
  private lastMissRefresh = 0

  constructor(private readonly make: (root: string) => Backend, private readonly roots: CaseRoots, private readonly opts: RouterOptions) {
    this.defaultStore = { root: opts.defaultRoot, caseRoot: null, backend: make(opts.defaultRoot), index: 0 }
  }

  /** 某案件的实例（没有就建）。 */
  private caseStore(caseRoot: string): Store {
    const k = pathKey(caseRoot)
    let s = this.stores.get(k)
    if (!s) {
      const root = join(caseRoot, CASE_SESSION_DIR)
// 案件根名单（T17 第三步，执行令 2026-09-30 15:16 第二节第 3 条）：会话存储路由按它决定"哪个 cwd 属于哪个案件"。
// 不取自 DSH 的工作区登记（工作区服务启动时要先 list 会话，会循环依赖）。Host 自己缓存一份：
// <应用数据>\案件根名单.json，只存路径；启动时先用缓存，工作台服务起来后按 GET /api/case/recent 刷新并写回。
// 刷新成功时名单以服务为准整个换掉（第三轮复核 B-F1）：服务按案件编号去重、只列现在的位置，案件文件夹复制到别处
// 再打开后旧位置不再列出；原先"没列出的保留"会让旧副本留在名单里且排在前面，续写落进旧文件夹。
import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'

export const CACHE_FILE = '案件根名单.json'

type LogFn = (level: 'info' | 'warn' | 'error', event: string, meta?: Record<string, unknown>) => void

/** 路径比较用的键：绝对路径、反斜杠、去掉末尾分隔符、不分大小写（Windows）。 */
export const pathKey = (p: string): string => resolve(p).replace(/\//g, '\\').replace(/\\+$/, '').toLowerCase()

/** cwd 是否就是这个案件根或在它里面。 */
export function inside(cwd: string, root: string): boolean {
  const c = pathKey(cwd)
  const r = pathKey(root)
  return c === r || c.startsWith(r + '\\')
}

const errorCode = (error: unknown): string => (error as NodeJS.ErrnoException)?.code ?? (error as Error)?.name ?? 'Error'

export class CaseRoots {
  private roots: string[] = []

  /**
   * @param cacheDir - 缓存文件所在目录（应用数据目录）；不给时只在内存里。
   * @param log - 缓存读写出错时记一条元数据日志，只记错误码（第三轮复核 A-P3-5）。
   */
  constructor(private readonly cacheDir?: string, private readonly log?: LogFn) {}

  /** 读缓存；文件不在或内容不对就当空名单（不报错，服务起来后会刷新）。文件在却读不出来时记一条日志。 */
  load(): this {
    if (!this.cacheDir) return this
    try {
      const v = JSON.parse(readFileSync(join(this.cacheDir, CACHE_FILE), 'utf8')) as { roots?: unknown }
      this.roots = Array.isArray(v.roots) ? v.roots.filter((x): x is string => typeof x === 'string' && x.length > 0) : []
    } catch (error) {
      this.roots = []
      if ((error as NodeJS.ErrnoException)?.code !== 'ENOENT') this.log?.('warn', 'session_store.case_roots_cache_unreadable', { code: errorCode(error) })
    }
    return this
  }

  list(): readonly string[] { return this.roots }

  /** 这个根（按路径键）在不在名单上。 */
  has(root: string): boolean {
    const k = pathKey(root)
    return this.roots.some((r) => pathKey(r) === k)
  }

  /** cwd 所属的案件根（最长的那个）；不在任何案件里返回 undefined。 */
  match(cwd: string | undefined): string | undefined {
    if (!cwd) return undefined
    let best: string | undefined
    for (const r of this.roots) if (inside(cwd, r) && (!best || pathKey(r).length > pathKey(best).length)) best = r
    return best
  }

  /**
   * 按 /api/case/recent 的结果把名单整个换掉：只留 exists 为真的根，路径以服务为准、按路径键去重、保持服务给的顺序。
   * 盘拔了（exists 为假）就不在名单里，插回来服务再报 exists 为真时加回。只在刷新成功时调用；刷新失败保留旧名单。
   * 有变化才写回缓存。服务返回空列表（一个案件也没有）时保留旧名单（第四轮复核 B-F6：服务的案件登记丢了、
   * 换了数据目录时不把案件会话一下子全藏起来；名单上多出的根读不到会话，没有害处）。
   * @returns 名单是否有变化。
   */
  replace(cases: ReadonlyArray<{ root: string; exists: boolean }>): boolean {
    if (cases.length === 0) return false
    const byKey = new Map<string, string>()
    for (const c of cases) {
      if (typeof c.root !== 'string' || !c.root || !c.exists) continue
      if (!byKey.has(pathKey(c.root))) byKey.set(pathKey(c.root), c.root)
    }
    const next = [...byKey.values()]
    const changed = next.length !== this.roots.length || next.some((r, i) => r !== this.roots[i])
    this.roots = next
    if (changed) this.save()
    return changed
  }

  private save(): void {
    if (!this.cacheDir) return
    try {
      const file = join(this.cacheDir, CACHE_FILE)
      mkdirSync(dirname(file), { recursive: true })
      const tmp = `${file}.${process.pid}.tmp`
      writeFileSync(tmp, JSON.stringify({ roots: this.roots }, null, 1), 'utf8')
      renameSync(tmp, file)
    } catch (error) {
      // 缓存写不进去只影响下次启动的初值，不影响本次；记一条日志好查
      this.log?.('warn', 'session_store.case_roots_cache_write_failed', { code: errorCode(error) })
    }
  }
}

