export async function apply(ctx: Ctx, config: Config): Promise<void> {
  const appData = config.appData ?? defaultAppData()
  const log: LogFn = makeLogger('session-store', appData, ctx.logger?.('lawbench-session-store'))
  if (!config.backend && !config.backendModule) throw new Error('lawbench-session-store: 没有给原版存储包的位置（backendModule）')
  const Jsonl = (config.backend as BackendClass | undefined)
    ?? ((await import(pathToFileURL(config.backendModule!).href)) as { default: BackendClass }).default
  // DSH 的 SessionPersistence 抽象基类（原版类的父类）：继承它，构造时即以 sessionPersistence 注册到本插件的上下文
  const Base = Object.getPrototypeOf(Jsonl) as new (ctx: Ctx) => object
  const roots = new CaseRoots(appData, log).load()
  const core = (): LawbenchCore | undefined => ctx.get('lawbenchCore') as LawbenchCore | undefined
  // 同一时间只问一次，5 秒内不重复问（list 可能被频繁调用）；服务还不在时不算问过
  const gate = firstRefreshGate(3000)
  let inFlight: Promise<void> | undefined
  let lastAt = 0
  const refresh = (force = false): Promise<void> => {
    if (inFlight) return inFlight
    if (!force && Date.now() - lastAt < 5000) return Promise.resolve()
    if (!core()?.endpoint()) return Promise.resolve()
    inFlight = refreshFromService(core(), roots, log)
      .then((ok) => { if (ok) { gate.mark(); void recheckWriters() } })
      .finally(() => { lastAt = Date.now(); inFlight = undefined })
    return inFlight
  }
  /**
   * 立刻按服务刷新一次名单并等它回来（每次问服务最多 3 秒（途中那次另等），之后放下要放下的写入者，每个最多 3 秒，见 refreshFromService 与 router.ts 的 recheck；第七轮复核 B-F4）。律师打开案件（caseOpen）之后服务才只列新位置，
   * Host 在 caseOpen 成功后、挂回游离会话之前调它（第四轮复核 B-F1）。正在途中的那次可能是打开之前发出的，等它完再问一次。
   */
  const refreshNow = async (): Promise<void> => {
    if (inFlight) await inFlight.catch(() => undefined)
    await refresh(true)
    await recheckWriters()
  }

  /**
   * 名单刷新后放下所属根已不在名单上、且还在盘上（复制）的写入者，或在原处接回（N55 ②，见 router.ts 的 recheck）。会话的 Agent 正在跑一轮的
   * 不打断，这一轮照原处落完，等它结束（agent/status 变 idle）再做。
   */
  const waiting = new Set<string>()
  const recheckOne = async (id: string): Promise<void> => {
    await router.recheck(id).catch((e: unknown) => {
      log('warn', 'session_store.writer_recheck_failed', { error: (e as Error)?.name ?? 'Error' })
    })
  }
  const recheckWriters = async (): Promise<void> => {
    const agents = ctx.get('agents') as { get(id: string): { status?: string } | undefined } | undefined
    for (const id of router.writersToRecheck()) {
      if (agents?.get(id)?.status !== 'running') { await recheckOne(id); continue }
      if (waiting.has(id)) continue
      waiting.add(id)
      const off = ctx.on('agent/status', (payload: { agent?: { id?: string }; status?: string }) => {
        if (payload?.agent?.id !== id || payload.status !== 'idle') return
        off(); waiting.delete(id)
        void recheckOne(id)
      })
    }
  }

  const router = new SessionRouter(
    (root) => new Jsonl(ctx.isolate('sessionPersistence'), { root, ...(config.compression ? { compression: config.compression } : {}) }),
    roots,
    {
      defaultRoot: config.defaultRoot, allowOutsideCase: config.allowOutsideCase ?? false, refresh, firstRefresh: gate, log,
      liveSeq: (id) => {
        const seq = (ctx.get('sessions') as { get(id: string): { seq?: number } | undefined } | undefined)?.get(id)?.seq
        return typeof seq === 'number' ? seq : undefined
      },
    },
  )

  class LawbenchSessionPersistence extends Base {
    readonly name = 'lawbench-session-store'
    create(header: Header, options?: never) { return router.create(header, options) }
    open(id: string, access: 'read' | 'write', options?: never) { return router.open(id, access, options) }
    flush() { return router.flush() }
    stat(id: string, options?: never) { return router.stat(id, options) }
    list(options?: never) { return router.list(options) }
    /** 我方加的（不在 DSH 的接口里）：Host 打开案件后调，见 refreshNow。 */
    refreshCaseRoots() { return refreshNow() }
    /** 我方加的：这个会话所在的案件文件夹已不在原位置（N55 ②，见 router.ts），我方 Agent 插件据此拒绝下一轮。 */
    caseMoved(id: string) { return router.caseMoved(id) }
    /** 我方加的：拒绝一轮之前放下还没落过盘的写入者（第十轮 R10-1，见 router.ts 的 releaseMoved）。 */
    releaseMoved(id: string) { return router.releaseMoved(id) }
    /** 我方加的：案件根名单上有没有这个根（Host 打开案件后核对刷新是否成功）。 */
    hasCaseRoot(root: string) { return roots.has(root) }
  }
  new LawbenchSessionPersistence(ctx)
  installDelete(ctx, router, log, config.trash)
  log('info', 'session_store.started', { case_roots: roots.list().length, allow_outside_case: config.allowOutsideCase ?? false })
  // 启动 30 秒后工作台的 Host 插件仍没起来（它的配置求值抛错、包缺失时 DSH 不报，界面一直转圈；T14 派修 4）：记一条元数据错误
  const hostWatch = setTimeout(() => { if (core() === undefined) log('error', 'session_store.host_missing', { after_s: HOST_WAIT_S }) }, HOST_WAIT_S * 1000)
  hostWatch.unref?.()

  // 投影缓存：原版类放进一个只隔离 storageDomain 的作用域，交给它按案件落盘的替身存储域；
  // 它对外仍以 sessionProjectionCache 提供。它要等 sessions（而 sessions 要等本插件），所以不等它起来。
  const pc = config.projectionCache
  if (pc && (pc.impl || pc.module)) {
    const mod = (pc.impl ? { default: pc.impl } : await import(pathToFileURL(pc.module!).href)) as {
      default: unknown; checkpointRecord?: { safeParse(v: unknown): { success: boolean; data?: unknown } }
    }
    const schema = mod.checkpointRecord
    const table = new CaseProjectionTable({
      caseRootOf: (id) => router.ownerOf(id),
      parse: (v) => {
        if (schema) { const r = schema.safeParse(v); return r.success ? (r.data as CacheRecord) : undefined }
        const rec = v as CacheRecord | null
        return rec && typeof rec === 'object' && rec.identity && typeof rec.identity === 'object' && rec.rows && typeof rec.rows === 'object' ? rec : undefined
      },
      log,
    })
    // 替身存储域由一个放在隔离作用域里的小插件提供：cordis 在提供者启用时只通知同一隔离作用域里的依赖方
    const cacheConfig = { writeEveryEvents: pc.writeEveryEvents, writeIntervalMs: pc.writeIntervalMs }
    void ctx.isolate('storageDomain').plugin({
      name: 'lawbench-session-projection-cache',
      apply: (scope: Ctx) => {
        scope.provide('storageDomain', caseProjectionDomain(table))
        scope.plugin(mod.default, cacheConfig)
      },
    })
  }

  // 工作台服务起来（或重启）后刷新一次名单；lawbenchCore 由 legal-host 提供，不是硬依赖（会话存储要比它先可用）
  ctx.inject(['lawbenchCore'], (c) => {
    const off = (c.lawbenchCore as LawbenchCore).onState((s) => { if (s === 'running') void refresh() })
    c.effect(() => off, 'lawbench-session-store: refresh case roots when the service runs')
    void refresh()
  })
}

/** 删除会话被拒的原因码（DSH 补丁 P-28 的 workspace/session-delete-check；界面按码给中文提示）。 */
export type DeleteRefusal = 'NOT_FOUND' | 'NOT_IN_CASE' | 'NO_RECYCLE_BIN' | 'RECORD_UNREADABLE'

/**
 * T30 删除会话（DSH 补丁 P-28）：会话存储是记录的拥有者，答两个事件。
 * - 预检 workspace/session-delete-check（停会话之前）：记录要找得到、在某个案件的 工作区\会话 下、那个位置有回收站，
 *   口径同服务"移除材料"的 trash.py（Windows 本机固定盘；Mac 与家目录同卷）。不过就给原因码，DSH 什么都不动（复核 rv-A67 P2-1）。
 * - 移走 workspace/session-delete（DSH 已停下并释放会话之后）：兜底关写句柄，记录目录移进回收站，再移这个会话的投影缓存；
 *   记录移不走就抛 TrashError（code 为 NO_RECYCLE_BIN / TRASH_FAILED），DSH 据此把左栏那行补回来、提示对话没有删除。
 *   缓存移不走只记日志：记录已进回收站，对话已删除，残留的缓存不会再被读到。
 * 日志只记元数据（原因码、第几步），不记路径。
 */
function installDelete(ctx: Ctx, router: SessionRouter, log: LogFn, deps?: TrashDeps): void {
  // 记录不在案件的 工作区\会话 下（默认根里的旧会话）不删；盘上还没有记录（空会话）的没东西要移，放行
  const refusal = async (id: string): Promise<DeleteRefusal | undefined> => {
    const rec = await router.recordOf(id)
    if (!rec) return 'NOT_FOUND'
    if (!rec.caseRoot || (rec.dir && !inside(rec.dir, join(rec.caseRoot, CASE_SESSION_DIR)))) return 'NOT_IN_CASE'
    if (rec.dir && !(await recycleBinAt(rec.dir, deps))) return 'NO_RECYCLE_BIN'
    return undefined
  }
  ctx.on('workspace/session-delete-check', async (request: { sessionId: string }, next: () => Promise<readonly string[]>) => {
    const why = await refusal(request.sessionId).catch((e: unknown): DeleteRefusal => {
      log('warn', 'session_store.delete_check_failed', { code: (e as NodeJS.ErrnoException)?.code ?? (e as Error)?.name ?? 'ERROR' })
      return 'RECORD_UNREADABLE'
    })
    if (why) log('info', 'session_store.delete_refused', { reason: why })
    return [...(why ? [why] : []), ...(await next())]
  })
  ctx.on('workspace/session-delete', async (request: { sessionId: string }) => {
    const id = request.sessionId
    // DSH 已释放会话。路由仍记着它属于哪个案件时，真正没落过盘的空会话返回 dir 为空；
    // 连所属案件都查不到，说明记录状态无法判断，不能当成空会话删掉。
    let rec: Awaited<ReturnType<typeof router.recordOf>>
    try {
      rec = await router.recordOf(id)
    } catch (e) {
      log('warn', 'session_store.delete_failed', { step: 'read', code: (e as NodeJS.ErrnoException)?.code ?? 'ERROR' })
      throw new TrashError('TRASH_FAILED', 'session record cannot be read')
    }
    if (!rec) {
      log('warn', 'session_store.delete_failed', { step: 'locate', code: 'NOT_FOUND' })
      throw new TrashError('TRASH_FAILED', 'session record cannot be located')
    }
    // 预检之后又变了（盘拔了、文件夹被挪）：照样拒，不移
    let why: DeleteRefusal | undefined
    try {
      why = await refusal(id)
    } catch (e) {
      log('warn', 'session_store.delete_failed', { step: 'recheck', code: (e as NodeJS.ErrnoException)?.code ?? 'ERROR' })
      throw new TrashError('TRASH_FAILED', 'session record cannot be rechecked')
    }
    if (why) throw new TrashError(why === 'NO_RECYCLE_BIN' ? 'NO_RECYCLE_BIN' : 'TRASH_FAILED', 'record cannot be recycled')
    await router.closeWriter(id)
    if (rec.dir) {
      try {
    const ch = String.fromCharCode(code)
    out += ch !== '~' && /^[A-Za-z0-9._-]$/.test(ch) ? ch : '~' + code.toString(16).toUpperCase().padStart(4, '0')
  }
  return out
}
const closeHandle = (h: Handle): Promise<void> => (h.close as () => Promise<void>).call(h)

export class SessionRouter {
  private readonly stores = new Map<string, Store>()
  private readonly owner = new Map<string, Store>()
  /** 成功 create 后尚未确认真正落盘的会话；pending 的 list/open/stat 可见性不算落盘，open 不能重新授予。 */
  private readonly neverPersisted = new Set<string>()
  private readonly defaultStore: Store
  private lastMissRefresh = 0

  constructor(private readonly make: (root: string) => Backend, private readonly roots: CaseRoots, private readonly opts: RouterOptions) {
    this.defaultStore = { root: opts.defaultRoot, caseRoot: null, backend: make(opts.defaultRoot), index: 0 }
  }

  /** 某案件的实例（没有就建）。 */
  private caseStore(caseRoot: string): Store {
    const k = pathKey(caseRoot)
    let s = this.stores.get(k)
    if (!s) {
      const root = join(caseRoot, CASE_SESSION_DIR)
      s = { root, caseRoot, backend: this.make(root), index: this.stores.size + 1 }
      this.stores.set(k, s)
    }
    return s
  }

  /** 此刻名单上的全部实例：默认根在前，再是各案件。建不起来的案件实例（根读不了）跳过。 */
  private all(): Store[] {
    const out = [this.defaultStore]
    for (const r of this.roots.list()) {
      try {
        out.push(this.caseStore(r))
      } catch (error) {
        this.skip({ root: r, caseRoot: r, backend: undefined as never, index: this.stores.size + 1 }, error)
      }
    }
    return out
  }

  /** 案件实例的读取加上限；默认根不加（它在本机软件目录里，出错照原样报）。 */
  private bounded<T>(s: Store, p: Promise<T>): Promise<T> {
    return s.caseRoot ? within(p, this.opts.caseRootTimeoutMs ?? 3000) : p
  }

  private skip(s: Store, error: unknown): void {
    // 只记元数据：第几个案件根、错误码；不记路径（路径里有当事人名）
    this.opts.log?.('warn', 'session_store.case_root_skipped', { index: s.index, code: (error as NodeJS.ErrnoException)?.code ?? 'ERROR' })
  }

  /** 交给 DSH 的记录头：案件实例里的会话，cwd 换成该案件现在的根（搬家后旧路径不再有效）。 */
  private header(s: Store, h: Header): Header {
    if (!s.caseRoot || (h.cwd !== undefined && pathKey(h.cwd) === pathKey(s.caseRoot))) return h
    return Object.freeze({ ...h, cwd: s.caseRoot })
  }

  private snapshot(s: Store, snap: Snapshot): Snapshot {
    const header = this.header(s, snap.header)
    return header === snap.header ? snap : { ...snap, header }
  }

  private persisted(w: Writer): void {
    w.seen = true
    this.neverPersisted.delete(w.id)
  }

  /**
   * 原版 storage 的自动批量和真实 session/flush 直接调用原句柄，不经过路由的 flush。
   * 在原句柄本身上观察成功写入，才能覆盖这些绕过路由的通路。
   */
  private observeWrites(w: Writer): void {
    const target = w.cur as unknown as Record<string, unknown>
    const wrap = (method: 'append' | 'flush' | 'drainLive'): void => {
      const original = target[method]
      if (typeof original !== 'function') return
      target[method] = async (...args: unknown[]): Promise<unknown> => {
        const buffered = method === 'drainLive'
          ? (w.cur as unknown as { buffered?: unknown[] }).buffered
          : undefined
        const hadBuffered = Array.isArray(buffered) && buffered.length > 0
        let result: unknown
        try {
          result = await Reflect.apply(original, w.cur, args)
        } catch (error) {
          // 原版 drain 逐批提交；后批失败时前批可能已经真实落盘。无法从整体拒绝判断“从未落盘”，
          // 因此保守撤销空会话删除资格，并保留原错误、缓冲和后续重试能力。
          if (method === 'drainLive' && hadBuffered) this.persisted(w)
          throw error
        }
        if (method === 'append' && (!Array.isArray(args[0]) || args[0].length === 0)) return result
        if (method !== 'drainLive' || hadBuffered) {
          this.persisted(w)
          return result
        }
        // 空 drain 没有事件要写；非空 drain 成功时原版已经完成物理写入，不能再用可失败的读取倒退事实。
        return result
      }
    }
    wrap('append')
    wrap('flush')
    wrap('drainLive')
  }

  /**
   * @param persisted - 打开时已由原版物理快照确认记录落盘（新建或 pending 为 false）。
   * @param created - 这是成功 create 返回的句柄；只有这里能首次授予“从未落盘”资格。
   */
  private handle(s: Store, h: Handle, persisted: boolean, created = false): Handle {
    if (persisted) this.neverPersisted.delete(h.id)
    else if (created) this.neverPersisted.add(h.id)
    const header = this.header(s, h.header)
    const writer = s.caseRoot && h.access === 'write'
    if (!writer && header === h.header) return h
    if (!writer) {
      return new Proxy(h, {
        get: (target, prop) => {
          if (prop === 'header') return header
          const v = Reflect.get(target, prop, target)
          return typeof v === 'function' ? v.bind(target) : v
        },
      })
    }
    // 记下这个写句柄属于哪个案件根，关闭时去掉（同一会话只记最新交出去的那个）。接回后真正的句柄换成新开的那个（w.cur），
    // 代理上的方法都转给它（第七轮复核 A-P3-3）
    const w: Writer = {
      id: h.id,
      at: s,
      cur: h,
      detached: false,
      // open 的补充 stat 可能暂缺；已有历史由 neverPersisted 中不存在体现，不能在这里倒退。
      seen: persisted || !this.neverPersisted.has(h.id),
    }
    this.writers.set(h.id, w)
    this.observeWrites(w)
    const close = async (): Promise<void> => {
      if (this.writers.get(w.id) === w) this.writers.delete(w.id)
      try {
        await closeHandle(w.cur)
      } finally {
        if (w.seen || this.onDisk(w)) this.persisted(w)
      }
    }
    return new Proxy(h, {
      get: (_target, prop) => {
        if (prop === 'header') return header
        if (prop === 'close' || prop === Symbol.asyncDispose) return close
        const v = Reflect.get(w.cur, prop, w.cur)
        return typeof v === 'function' ? v.bind(w.cur) : v
      },
    })
  }

  /** 路由交出去、还没关的案件写句柄（按会话编号）。 */
  private readonly writers = new Map<string, Writer>()

  private invalid(w: Writer): boolean {
    return !this.current(w.at) || !existsSync(w.at.caseRoot!) || this.recordGone(w)
  }

  /** 这个会话的记录目录（<案件>\工作区\会话\<项目>\<编号>）在不在盘上。原版按建会话时的 cwd 编项目目录，这里不重算，逐个项目目录找。 */
  private onDisk(w: Writer): boolean {
    const seg = encodeSegment(w.id)
    try {
      return readdirSync(w.at.root, { withFileTypes: true }).some((e) => e.isDirectory() && existsSync(join(w.at.root, e.name, seg)))
    } catch {
      return false
    }
  }

  /**
   * 案件根还在、也在名单上，但这个会话自己的记录已不在（第八轮复核 B-F2：搬家后原路径上又建了另一个案件并打开）。
   * 只对见过记录的会话判：新建的会话在原版第一次落盘之前盘上本来就没有。
   */
  private recordGone(w: Writer): boolean {
    if (!w.seen) {
      if (this.onDisk(w)) this.persisted(w)
      return false
    }
    return !this.onDisk(w)
  }

  /**
   * 要放下：根已不在名单上、但还在盘上（复制后在新位置打开）。根不在盘上（拔盘、搬家）不放下，见 recheck。
   * 原版还没落过盘的写入者（新建、还没说话的会话，如进案件时 DSH 默认建的空白对话）根不在盘上也放下：它缓冲里没有东西可丢，
   * 不放下的话被拒那一轮的事件会让原版落盘时把旧路径整条重建、把话写进去（第十轮 R10-1）。
   */
  private toDetach(w: Writer): boolean {
    return !w.detached && !this.current(w.at) && (!w.seen || existsSync(w.at.caseRoot!))
  }

  /**
   * 这个会话的写句柄所属案件根已不在当前名单上、或已不在盘上，或写入者已放下（N55 ②"位置失效"）：我方 Agent 插件据此拒绝下一轮。
   * 名单只在刷新成功时换，所以刷新失败不会误判；根回到名单、盘插回后解除（放下过的见 recheck）。
   */
  caseMoved(id: string): boolean {
    const w = this.writers.get(id)
    return !!w && (w.detached || this.invalid(w))
  }

  /** 名单刷新后要 recheck 的会话：要放下的；放下了、根又回到名单且在盘上的。 */
  writersToRecheck(): string[] {
    return [...this.writers.values()].filter((w) => (w.detached ? !this.invalid(w) : this.toDetach(w))).map((w) => w.id)
  }

  /**
   * 名单刷新成功后由会话存储插件调（这个会话的 Agent 空闲时）。DSH 被拒的一轮也会把律师那句话和"一轮被拦下"记进会话
   * （live-writer.spec），活着的写入者会把它们写进旧处；所以根已不在名单上、还在盘上（复制后在新位置打开）时先放下写入者：
   * 关掉真正的句柄（原版把缓冲的事件落完、注销写入者），之后这个会话的事件哪里都不写，旧处不再变。关最多等 3 秒（盘慢、
   * 网络盘挂住），到时没关完就让它在后台接着关，照样记为已放下（第七轮复核 B-F4）；后台关完之前进来的事件原版
   * 仍一并落进旧处（第八轮复核 B-F4，已知限制）。接回时的打开、读取同样最多等 3 秒（第八轮复核 B-F5）。
   * 根不在盘上（拔盘、搬家）不放下（第七轮复核 B-F1）：此时关句柄落不了盘，原版照样注销，缓冲里的事件（比如拔盘时正在跑的
   * 那一轮的回答）就永久丢了；留着写入者，原版写不进去会留着缓冲下次再写，插回后接上。
   * 根回到名单（重新打开原位置）且盘上记录与内存里的会话一样长时，在原处重新以写方式打开接着写；内存事件数在读完盘上记录
   * 之后再取（第七轮复核 A-P2-1：取早了，取数之后、登记新写入者之前律师发的那句被原版丢掉，比对却判一样长，接回后序号
   * 接不上，整段对话静默不落盘）。不一样长（放下期间又被拒过一轮，这几条只在内存里）就一直算位置失效，重启后从盘上读。
   */
  recheck(id: string): Promise<void> {
    return this.queue(id, () => this.recheckOnce(id))
  }

  /**
   * 我方 Agent 插件拒绝一轮之前调（第十轮 R10-1）：这个会话位置失效、写入者原版还没落过盘，就立刻放下（关句柄最多等 3 秒）。
   * 律师这一句在拒绝之前已进了原版写入者的缓冲（`agent/inbox/spliced` 先于 `agent/pre-step`），关句柄会先把缓冲落盘——
   * 没落过盘的会话落盘时原版 mkdir 整条路径，旧路径就被重建、话写进去（复核员 B 第九轮 M1b）；它的批量计时器几十毫秒后
   * 也会自己落盘。所以先清空缓冲再关：这里面只有被拒这一轮的事件，本来就不保存（10.4）。缓冲是原版句柄的私有字段
   * `buffered`（PATCHES.md 核对清单 ⑩）；没有这个字段时照常关并记一条日志。
   * 放下后一直算位置失效，接回时打开找不到这个会话就不接回。
   */
  releaseMoved(id: string): Promise<void> {
    return this.queue(id, async () => {
      const w = this.writers.get(id)
      if (!w || w.detached || w.seen || !this.caseMoved(id)) return
      const raw = w.cur as unknown as { buffered?: unknown }
      if (Array.isArray(raw.buffered)) raw.buffered.length = 0
      else this.opts.log?.('warn', 'session_store.buffer_drop_unsupported', { index: w.at.index })
      await within(closeHandle(w.cur), this.opts.caseRootTimeoutMs ?? 3000)
        .catch((e: unknown) => this.opts.log?.('warn', 'session_store.writer_detach_failed', { index: w.at.index, error: (e as Error)?.name ?? 'Error' }))
      w.detached = true
      this.opts.log?.('info', 'session_store.writer_detached', { index: w.at.index })
    })
  }

  /** 同一会话的放下、接回排成一队（打开案件后的刷新、后台刷新、拒绝前的放下可能同时来）。 */
  private queue(id: string, fn: () => Promise<void>): Promise<void> {
    const run = (this.rechecking.get(id) ?? Promise.resolve()).then(fn)
    const tail = run.catch(() => undefined)
    this.rechecking.set(id, tail)
    void tail.then(() => { if (this.rechecking.get(id) === tail) this.rechecking.delete(id) })
    return run
  }

  private readonly rechecking = new Map<string, Promise<void>>()

  private async recheckOnce(id: string): Promise<void> {
    const w = this.writers.get(id)
    if (!w) return
    const fail = (event: string, error: unknown): void => {
      // 只记元数据：第几个案件根、错误名
      this.opts.log?.('warn', event, { index: w.at.index, error: (error as Error)?.name ?? 'Error' })
    }
    if (this.toDetach(w)) {
      // 关完（或到时）再记"已放下"：同时来的另一次 recheck 排在这次后面，看到的是关完之后的状态（打开案件后要等它再返回）
      await within(closeHandle(w.cur), this.opts.caseRootTimeoutMs ?? 3000).catch((e: unknown) => fail('session_store.writer_detach_failed', e))
      w.detached = true
      this.opts.log?.('info', 'session_store.writer_detached', { index: w.at.index })
    } else if (w.detached && !this.invalid(w) && this.opts.liveSeq) {
      let fresh: Handle
      const opening = w.at.backend.open(id, 'write')
      try {
        fresh = await within(opening, this.opts.caseRootTimeoutMs ?? 3000)
      } catch (e) {
        fail('session_store.writer_reattach_failed', e)
        // 到时之后那次打开迟到返回的句柄没人用，关掉（第九轮复核 B-F5）
        void opening.then((h) => closeHandle(h).catch(() => undefined), () => undefined)
        return
      }
      let n = -1
      try {
        n = (await within((fresh.read as () => Promise<{ events: unknown[] }>).call(fresh), this.opts.caseRootTimeoutMs ?? 3000)).events.length
      } catch (e) { fail('session_store.writer_reattach_failed', e) }
      if (n !== this.opts.liveSeq(id) || this.writers.get(id) !== w) {
        // 关新句柄也设上限：读到时之后关也可能挂住，recheck 不返回，打开案件就一直等（第十轮 R10-2）
        await within(closeHandle(fresh), this.opts.caseRootTimeoutMs ?? 3000).catch(() => undefined)
        return
      }
      w.cur = fresh
      w.detached = false
      this.opts.log?.('info', 'session_store.writer_reattached', { index: w.at.index })
    }
  }

  async create(header: Header, options?: Opts): Promise<Handle> {
    let caseRoot = this.roots.match(header.cwd)
    if (!caseRoot && header.cwd && this.opts.refresh) {
      // 刚登记的案件可能还不在名单里：问一次服务再判
      await this.opts.refresh(true).catch(() => undefined)

        } else {
          reject(new Error('session migration preparation failed', { cause: error }))
        }
      },
    )
  })
}

/**
 * The JSONL persistence backend. Load as a plugin; it registers as
 * `ctx.sessionPersistence`. Sessions materialize lazily: a created session is
 * visible to this process immediately, reaches disk on its first append or
 * flush, and never existed if the process crashes before that.
 */
class JsonlSessionPersistence extends SessionPersistence {
  static Config: z<Config> = z.object({
    root: z.string().required(),
    compression: JsonlCompressionSchema,
  })

  /** Backend label for diagnostics and effects; shadows `Service.name` without changing the service key. */
  override readonly name = 'session-persistence-jsonl'

  private root: string
  private compression: JsonlCompression
  private rootEncodingCheck: Promise<void> | undefined
  private readonly tracker = new JsonlBackendTracker(this.name)
  private readonly generationFormat: Omit<JsonlGenerationFormatAdapter, 'createRestore'>
  /**
   * Bounded LRU of parsed, validated stored logs keyed by session id and
   * guarded by the stat-derived revision, so an immediate cold-read handoff
   * (observation then resume) parses the artifact once. Every local mutation
   * for an id invalidates its entry; a foreign write misses through the
   * revision guard.
   */
  private readonly coldLogMemo = new Map<SessionId, StoredLog>()
  /** One joinable decode/migration operation per selected historical Session file revision. */
  private readonly migrationPreparations = new Map<SessionId, MigrationPreparation>()

  constructor(ctx: Context, public config: Config) {
    super(ctx)
    /* v8 ignore next 5 -- generated catalog and Session source share one build-time version owner. */
    if (sessionFormatCatalog.currentVersion !== SESSION_FORMAT_VERSION) {
      throw new Error(
        `session-persistence-jsonl: format catalog v${sessionFormatCatalog.currentVersion} `
        + `does not match Session v${SESSION_FORMAT_VERSION}`,
      )
    }
    // Resolve once so later process.cwd() changes cannot split one backend across roots.
    this.root = resolve(config.root)
    this.compression = config.compression ?? DEFAULT_COMPRESSION
    this.generationFormat = {
      currentVersion: sessionFormatCatalog.currentVersion,
      encodeHeader: (header, inheritedEventCount) =>
        sessionFormatCatalog.encodeCurrentHeader(header, inheritedEventCount),
      encodeEvent: event => sessionFormatCatalog.encodeCurrentEvent(event),
      isUnsupportedMigrationError: (error): error is SessionFormatUnsupportedMigrationError =>
        error instanceof SessionFormatUnsupportedMigrationError,
    }
    this.assertUsableRoot()
    this.tracker.install(ctx)
  }

  /**
   * Refusal-diagnostics hook: the absolute target path, without touching the filesystem.
   * @param meta - the stored header naming the session and its cwd.
   * @returns the artifact kind and absolute path.
   */
  private locate(meta: SessionHeader): SessionLocation {
    return { kind: 'jsonl', path: logPath(this.root, meta.cwd, meta.id, this.compression) }
  }

  // --- SessionPersistence service API ---

  /**
   * Create a new stored session and take its write ownership. The session is
   * visible to this process immediately; the physical artifact appears on the
   * first append or flush.
   * @param header - the immutable header to store; must be losslessly
   *   JSON-serializable with a non-negative safe-integer `createdAt`.
   * @param options - optional cancellation.
   * @returns the owned write handle.
   */
  async create(header: SessionHeader, options?: SessionPersistenceCreateOptions): Promise<SessionHandle> {
    options?.signal?.throwIfAborted()
    const snapshot = materializeCreateHeader(header)
    // Fail fast on a seeded/cut mismatch with the exact refusal the header
    // line encoder enforces at materialization.
    toHeaderLine(snapshot, options?.inheritedEventCount)
    const inheritedEventCount = SessionLogOffset(options?.inheritedEventCount ?? 0)
    await this.ensureRootEncoding()
    options?.signal?.throwIfAborted()
    if (this.tracker.hasPending(snapshot.id) || await this.findLog(snapshot.id, options?.signal) !== undefined) {
      throw new SessionAlreadyExistsError(snapshot.id)
    }
    options?.signal?.throwIfAborted()
    // No lock yet: before materialization there is no durable artifact for
    // another process to contend over, so the handle acquires the lock right
    // before its first log bytes publish (ensureLease); an unmaterialized
    // session leaves no filesystem footprint at all.
    this.tracker.registerCreated(snapshot, inheritedEventCount)
    return this.tracker.adopt(new JsonlSessionHandle(this, snapshot.id, snapshot, 'write', { cursor: 0, materialized: false, inheritedEventCount }))
  }

  /**
   * Open an existing stored session for `read` or single-writer `write`.
   * @param id - the stored session to open.
   * @param access - `read` (no ownership) or `write` (atomic in-process claim).
   * @param options - optional cancellation.
   * @returns the open handle.
   */
  async open(id: SessionId, access: SessionAccess, options?: SessionPersistenceOpenOptions): Promise<SessionHandle> {
    options?.signal?.throwIfAborted()
    await this.ensureRootEncoding()
    options?.signal?.throwIfAborted()
    const pending = this.tracker.pendingOf(id)
    if (access === 'read') {
      if (pending !== undefined) {
        return this.tracker.adopt(new JsonlSessionHandle(this, id, pending.header, 'read', { cursor: 0, materialized: false, inheritedEventCount: pending.inheritedEventCount }))
      }
      let stored: StoredLog
      try {
        stored = await this.requireStoredLog(id, options?.signal)
      } catch (error: unknown) {
        if (!(error instanceof JsonlGenerationSourceChangedError)) throw error
        stored = await this.requireStoredLog(id, options?.signal)
      }
      let state: StorageHandleState
      if (stored.status === 'prepared') {
        state = {
          cursor: 0,
          materialized: true,
          inheritedEventCount: stored.inheritedEventCount,
          primed: stored,
        }
      } else {
        state = {
          cursor: 0,
          materialized: true,
          inheritedEventCount: stored.inheritedEventCount,
        }
      }
      return this.tracker.adopt(new JsonlSessionHandle(this, id, stored.meta, 'read', state))
    }
    // A pending entry always belongs to an ACTIVE creator handle (close erases
    // it), so the claim below rejects that case as already owned.
    this.tracker.claimWrite(id)
    let lease: SessionWriteLease | undefined
    try {
      const resolved = await this.findLog(id, options?.signal)
      if (resolved === undefined) throw new SessionPersistenceNotFoundError(id)
      lease = await this.acquireLease(id, undefined, dirname(resolved.currentPath))
      const prepared = await this.requireStoredLog(id, options?.signal)
      options?.signal?.throwIfAborted()
      let stored: CurrentStoredLog
      if (prepared.status === 'prepared') {
        stored = await this.publishStoredMigration(id, prepared)
      } else {
        stored = prepared
      }
      options?.signal?.throwIfAborted()
      return this.tracker.adopt(new JsonlSessionHandle(this, id, stored.meta, 'write', {
        cursor: stored.events.length,
        materialized: true,
        tornTruncateTo: stored.tornTruncateTo,
        recoveredTail: stored.recoveredTail,
        inheritedEventCount: stored.inheritedEventCount,
        primed: stored,
      }, lease))
    } catch (error) {
      // Free the in-process claim no matter how the kernel-lock release
      // fares, and keep the original diagnostic: a release failure joins it
      // instead of replacing it.
      /* v8 ignore next -- typed backends and fs reject with Error */
      const failure = error instanceof Error ? error : new Error(String(error))
      let releaseFailure: Error | undefined
      try {
        await lease?.release()
      } catch (raw: unknown) {
        /* v8 ignore next -- lock releases reject with Error */
        releaseFailure = raw instanceof Error ? raw : new Error(String(raw))
      }
      this.tracker.releaseClaim(id)
      if (releaseFailure !== undefined) {
        throw new AggregateError([failure, releaseFailure], `session "${id}": write open failed and its lock release failed`)
      }
      throw failure
    }
  }

  /**
   * Flush every active write handle in one durability barrier; see the seam
   * contract.
   * @returns resolution once every write handle active at the call has flushed.
   */
  flush(): Promise<void> {
    return this.tracker.flushAll()
  }

  /**
   * Observe one stored session without reading its event log.
   * @param id - the stored session to observe.
   * @param options - optional cancellation.
   * @returns the snapshot (`sizeBytes` carries the physical artifact size), or
   *   `undefined` when the session does not exist.
   */
  async stat(
    id: SessionId,
    options?: SessionPersistenceStatOptions,
  ): Promise<SessionPersistenceSnapshot | undefined> {
    options?.signal?.throwIfAborted()
    await this.ensureRootEncoding()
    options?.signal?.throwIfAborted()
    const pending = this.tracker.pendingOf(id)
    if (pending !== undefined) {
      return { header: pending.header, revision: pending.revision }
    }
    const selected = await this.findLog(id, options?.signal)
    if (selected === undefined) return undefined
    const header = await this.readGenerationHeader(selected, id, options?.signal)
    if (header === undefined) return undefined
    try {
      const identity = await stat(selected.sourcePath, { bigint: true })
      options?.signal?.throwIfAborted()
      return {
        header,
        revision: selected.sourceVersion < SESSION_FORMAT_VERSION
          ? SessionPersistenceRevision(`${fileRevision(identity)}:${await this.historicalCorpusRevision(options?.signal)}`)
          : fileRevision(identity),
        sizeBytes: Number(identity.size),
      }
    } catch (error: unknown) {
      options?.signal?.throwIfAborted()
      if (isENOENT(error)) return undefined
      throw error
    }
  }

  /**
   * List every stored session visible to this process: materialized artifacts
   * plus this process's created-but-unmaterialized sessions.
   * @param options - optional cancellation.
   * @returns one snapshot per session, in no promised order.
   */
  async list(options?: SessionPersistenceListOptions): Promise<readonly SessionPersistenceSnapshot[]> {
    const signal = options?.signal
    const snapshots: SessionPersistenceSnapshot[] = []
    const listed = new Set<SessionId>()
    // Snapshot pending entries BEFORE scanning storage: a session whose first
    // append lands mid-scan is then still in this snapshot (its artifact may
    // predate the scan), so create-to-list visibility never has a hole.
    const pending = [...this.tracker.pendingEntries()]
    const artifacts = await this.listArtifacts(signal)
    const corpusRevision = artifacts.some(artifact => artifact.sourceVersion < SESSION_FORMAT_VERSION)
      ? await this.historicalCorpusRevision(signal) : undefined
    for (const artifact of artifacts) {
      signal?.throwIfAborted()
      try {
        const identity = await stat(artifact.path, { bigint: true })
        signal?.throwIfAborted()
        listed.add(artifact.header.id)
        snapshots.push({
          header: artifact.header,
          revision: artifact.sourceVersion < SESSION_FORMAT_VERSION
            ? SessionPersistenceRevision(`${fileRevision(identity)}:${corpusRevision}`)
            : fileRevision(identity),
          sizeBytes: Number(identity.size),
        })
      } catch (error: unknown) {
        signal?.throwIfAborted()
        if (!isENOENT(error)) throw error
      }
    }
    for (const [id, entry] of pending) {
      if (!listed.has(id)) snapshots.push({ header: entry.header, revision: entry.revision })
    }
    signal?.throwIfAborted()
    return snapshots
  }

  // --- handle-facing storage internals (package-private via the handle class below) ---

  /** Resolve and read one stored log, refusing loudly when the artifact is absent. */
  private async requireStoredLog(id: SessionId, signal?: AbortSignal): Promise<StoredLog> {
    const selected = await this.findLog(id, signal)
    if (selected === undefined) throw new SessionPersistenceNotFoundError(id)
    if (selected.sourceVersion < SESSION_FORMAT_VERSION) {
      const sourceRevision = fileRevision(await stat(selected.sourcePath, { bigint: true }))
      signal?.throwIfAborted()
      let preparation = this.migrationPreparations.get(id)
      if (preparation === undefined
        || preparation.sourcePath !== selected.sourcePath
        || preparation.sourceRevision !== sourceRevision) {
        const controller = new AbortController()
        const promise = this.loadStoredMigration(id, selected, sourceRevision, controller.signal)
        preparation = {
          sourcePath: selected.sourcePath,
          sourceRevision,
          controller,
          promise,
          settled: false,
          waiters: 0,
        }
        this.migrationPreparations.set(id, preparation)
        const created = preparation
        const release = (): void => {
          created.settled = true
          if (this.migrationPreparations.get(id) === created) {
            this.migrationPreparations.delete(id)
          }

/**
 * Build the header line object from a {@link SessionHeader}.
 * @param header - the immutable session metadata to serialize.
 * @param inheritedEventCount - exact inherited prefix length; required for a
 * seeded header and omitted only for an unseeded header.
 * @returns the `type: 'session'`-tagged line object, absent optional fields omitted (never null).
 */
export function toHeaderLine(
  header: SessionHeader,
  inheritedEventCount?: SessionLogOffsetType,
): HeaderLine {
  if (header.isSeeded && inheritedEventCount === undefined) {
    throw new Error('seeded session header requires an inherited event count')
  }
  const cut = SessionLogOffset(inheritedEventCount ?? 0)
  if (!header.isSeeded && cut !== 0) {
    throw new Error('unseeded session header inherited event count must be 0')
  }
  return sessionFormatCatalog.encodeCurrentHeader({
    ...header,
    delegationDepth: header.delegationDepth ?? 0,
  }, cut) as unknown as HeaderLine
}

/**
 * Translate one current physical header into logical metadata and its cut.
 * @param line - the shape-checked first line of a log (see the `isHeaderLine` guard).
 * @returns logical Session metadata paired with the exact inherited prefix length.
 */
function fromHeaderLine(line: HeaderLine): SessionStorageMetadata {
  return {
    meta: {
      version: SESSION_FORMAT_VERSION,
      id: line.id,
      createdAt: line.createdAt,
      ...line.cwd !== undefined ? { cwd: line.cwd } : {},
      ...line.parentSession !== undefined ? { parentSession: line.parentSession } : {},
      isSeeded: line.isSeeded,
      ...line.origin !== undefined ? { origin: line.origin } : {},
      delegationDepth: line.delegationDepth,
      ...line.agentPreset !== undefined ? { agentPreset: line.agentPreset } : {},
    },
    inheritedEventCount: SessionLogOffset(0),
  }
}

/** Type guard: a parsed first line is a well-formed session header. */
function isHeaderLine(value: unknown): value is HeaderLine {
  return (
    typeof value === 'object' && value !== null && !Array.isArray(value)
    && HEADER_REQUIRED_KEYS.every(key => Object.hasOwn(value, key))
    && Object.keys(value).every(key => HEADER_KEYS.has(key))
    && (value as { type?: unknown }).type === 'session'
    && typeof (value as { version?: unknown }).version === 'number'
    && typeof (value as { id?: unknown }).id === 'string'
    && typeof (value as { createdAt?: unknown }).createdAt === 'number'
    && Number.isSafeInteger((value as { createdAt: number }).createdAt)
    && (value as { createdAt: number }).createdAt >= 0
    && !Object.is((value as { createdAt: number }).createdAt, -0)
    && typeof (value as { delegationDepth?: unknown }).delegationDepth === 'number'
    && Number.isSafeInteger((value as { delegationDepth: number }).delegationDepth)
    && (value as { delegationDepth: number }).delegationDepth >= 0
    && !Object.is((value as { delegationDepth: number }).delegationDepth, -0)
    && ((value as { cwd?: unknown }).cwd === undefined
      || (typeof (value as { cwd?: unknown }).cwd === 'string'
        && isAbsolute((value as { cwd: string }).cwd)))
    && ((value as { parentSession?: unknown }).parentSession === undefined
      || typeof (value as { parentSession?: unknown }).parentSession === 'string')
    && typeof (value as { isSeeded?: unknown }).isSeeded === 'boolean'
    && ((value as { origin?: unknown }).origin === undefined
      || (value as { origin?: unknown }).origin === 'subagent')
    && ((value as { agentPreset?: unknown }).agentPreset === undefined
      || typeof (value as { agentPreset?: unknown }).agentPreset === 'string')
  )
}

/**
 * Encode an arbitrary string as a single safe path segment, injectively over ALL JS (UTF-16)
 * strings — including lone surrogates. A {@link SessionId} is an unvalidated branded string,
 * so this neutralizes `../`, absolute paths, NUL, and separators before any filesystem use.
 * Safe code units remain literal; every other unit, including `~`, becomes
 * `~XXXX`. Operating on code units preserves lone surrogates, while special-
 * casing `.` and `..` prevents traversal by an otherwise safe whole segment.
 *
 * @param raw - the string to encode; must be non-empty (throws on `''`).
 * @returns the escaped single path segment, decodable back to `raw`.
 */
export function encodeSegment(raw: string): string {
  if (raw.length === 0) throw new Error('cannot encode an empty path segment')
  if (raw === '.') return '~002E'
  if (raw === '..') return '~002E~002E'
  let out = ''
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i)
    const ch = String.fromCharCode(code)
    if (ch !== '~' && /^[A-Za-z0-9._-]$/.test(ch)) {
      out += ch
    } else {
      out += '~' + code.toString(16).toUpperCase().padStart(4, '0')
    }
  }
  return out
}

/**
 * Build the readable directory key for a project path.
 * Filesystem separators and drive separators become `-`; unsafe code units use
 * the same `~XXXX` escape as session ids. The key is bounded for filesystem
 * component limits. Separator replacement and truncation are intentionally
 * lossy, following the common human-navigable project-directory convention.
 * @param cwd - the session's project directory.
 * @returns a single filesystem-safe project directory name.
 */
export function projectKey(cwd: string): string {
  if (cwd.length === 0) throw new Error('cannot encode an empty project path')
  let readable = ''
  let separatorRun = false
  for (let i = 0; i < cwd.length; i++) {
    const code = cwd.charCodeAt(i)
    const ch = String.fromCharCode(code)
    if (ch === '/' || ch === '\\' || ch === ':') {
      if (!separatorRun) readable += '-'
      separatorRun = true
    } else if (ch !== '~' && /^[A-Za-z0-9._-]$/.test(ch)) {
      readable += ch
      separatorRun = false
    } else {
      readable += '~' + code.toString(16).toUpperCase().padStart(4, '0')
      separatorRun = false
    }
  }
  const slug = readable.replace(/^-+/, '') || 'root'
  return `--${slug.slice(0, 251)}--`
}

/**
 * The configured root's human-navigable project directory. A configured root
 * may be local or shared; this grouping does not prescribe its deployment.
 * @param root - the backend's session root directory.
 * @param cwd - the session's project directory; `undefined` selects `_no-cwd`.
 * @returns the project directory path under `root`.
 */
export function projectDir(root: string, cwd: string | undefined): string {
  if (cwd === undefined) return join(root, '_no-cwd')
  return join(root, projectKey(cwd))
}

/**
 * The directory owned by one session and available for future session-local
 * artifacts.
 * @param root - the backend's session root directory.
 * @param cwd - the session's project directory.
 * @param id - the session id, encoded to one safe path segment.
 * @returns the session directory beneath its project directory.
 */
export function sessionDir(root: string, cwd: string | undefined, id: SessionId): string {
  return join(projectDir(root, cwd), encodeSegment(id))
}

/**
 * Build one immutable Session format generation path.
 * @param root - the backend's session root directory.
 * @param cwd - the session's project directory (`undefined` → `_no-cwd`).
 * @param id - the session id, path-encoded via {@link encodeSegment} before filesystem use.
 * @param version - physical Session format generation.
 * @param compression - physical artifact encoding and filename suffix.
 * @returns the selected generation's configured JSONL artifact path.
 */
export function generationLogPath(
  root: string,
  cwd: string | undefined,
  id: SessionId,
  version: number,
  compression: JsonlCompression,
): string {
  return join(sessionDir(root, cwd, id), generationLogFilename(version, compression))
}

/**
 * Build the current generation's append target path for a Session.
 * @param root - the backend's session root directory.
 * @param cwd - the session's project directory (`undefined` → `_no-cwd`).
 * @param id - the session id, path-encoded via {@link encodeSegment} before filesystem use.
 * @param compression - physical artifact encoding and filename suffix.
 * @returns the current Session format generation path.
 */
export function logPath(
  root: string,
  cwd: string | undefined,
  id: SessionId,
  compression: JsonlCompression,
): string {
  return generationLogPath(root, cwd, id, SESSION_FORMAT_VERSION, compression)
}

/**
 * Serialize a current event batch as JSONL lines (no trailing newline). Compact
 * Assistant streams are nested event data; every event occupies one row.
 * @param events - the batch to serialize, in log order.
 * @returns the batch's JSONL text; the writer adds the final newline.
 */
export function eventLines(events: readonly SessionEvent[]): string {
  return events.map(eventLine).join('\n')
}

/**
 * Serialize one current event as one JSONL record without its trailing newline.
 * @param event - current event to encode.
 * @returns one physical JSON record.

interface ProductionSetup {
  readonly live: ProductionContext
  readonly commands: {
    create(input: { readonly cwd: string }): Promise<{ readonly sessionId: string }>
    fork(input: { readonly sessionId: string }): Promise<{ readonly sessionId: string }>
    prompt(input: {
      readonly sessionId: string
      readonly requestId: string
      readonly mode: 'queue'
      readonly content: readonly { readonly type: 'text'; readonly text: string }[]
    }): Promise<unknown>
  }
  readonly BrowserSession: new (id: unknown, options: Record<string, never>) => BrowserSessionInstance
  readonly SessionLogOffset: (offset: number) => unknown
  readonly persistenceRoot: string
  readonly workspaceRoot: string
  reopenPersistedEvents(sourceSessionId: string, childSessionId: string): Promise<{
    readonly source: readonly NativeEvent[]
    readonly child: readonly NativeEvent[]
  }>
}

async function setupProduction(
  runRoot: string,
  resolveCredential: () => string,
  acceptContext: (context: ProductionContext) => void,
): Promise<ProductionSetup> {
  const [Cordis, Llm, SessionModule, SystemPromptModule, ToolsModule, ProjectionsModule,
    AgentModule, AgentLoopModule, PersistenceModule, QueryModule, TypertModule,
    PiAiModule, ControllerAgentModule, ControllerCommandsModule,
    ControllerProjectionModule, ClientSessionModule] = await Promise.all([
    import(modulePath('vendor/cordis/lib/index.js')),
    import(modulePath('packages/llm/llm/src/index.ts')),
    import(modulePath('packages/core/session/src/index.ts')),
    import(modulePath('packages/core/system-prompt/src/index.ts')),
    import(modulePath('packages/core/tools/src/index.ts')),
    import(modulePath('packages/session/session-projection/src/index.ts')),
    import(modulePath('packages/core/agent/src/index.ts')),
    import(modulePath('packages/core/agent-loop/src/index.ts')),
    import(modulePath('packages/session/session-persistence-jsonl/src/index.ts')),
    import(modulePath('packages/session-query/session-query/src/index.ts')),
    import(modulePath('packages/typert/registry/src/index.ts')),
    import(modulePath('packages/llm/llm-pi-ai/src/index.ts')),
    import(modulePath('packages/api/session-controller/src/agent.ts')),
    import(modulePath('packages/api/session-controller/src/commands.ts')),
    import(modulePath('packages/api/session-controller/src/model-selection-projection.ts')),
    import(modulePath('packages/api/session-controller/src/client/sessions/session.ts')),
  ])

  const Context = Cordis.Context
  const LlmRuntime = Llm.default
  const SessionStore = SessionModule.default
  const SessionLogOffset = SessionModule.SessionLogOffset
  const SystemPrompt = SystemPromptModule.default
  const ToolRuntime = ToolsModule.default
  const SessionProjectionRegistry = ProjectionsModule.default
  const AgentRegistry = AgentModule.default
  const AgentLoop = AgentLoopModule.default
  const JsonlSessionPersistence = PersistenceModule.default
  const SessionQueryEngine = QueryModule.SessionQueryEngine
  const TypertRegistry = TypertModule.default
  const ApiSessionAgentController = ControllerAgentModule.ApiSessionAgentController
  const SessionCommandController = ControllerCommandsModule.SessionCommandController
  const installModelSelectionProjection = ControllerProjectionModule.installModelSelectionProjection
  const BrowserSession = ClientSessionModule.Session

  const live = new Context()
  acceptContext(live as unknown as ProductionContext)
  await live.plugin(TypertRegistry)
  await live.plugin(LlmRuntime)
  await live.plugin(SessionStore)
  await live.plugin(SessionProjectionRegistry)
  await live.plugin(SystemPrompt, { personaPrefix: '' })
  await live.plugin(ToolRuntime)
  await live.plugin(AgentRegistry)

  live.provide('agentDefaultModel', {
    currentSelection: () => ({ provider: PROVIDER, model: MODEL }),
    saveSelection: async () => {},
  })
  live.provide('workspaceRegistry', {
    archivedSessionIds: [],
    get: () => undefined,
    list: () => [],
  })
  live.provide('attachments', {
    imageLimits: {
      maxImageBytes: 5 * 1024 * 1024,
      maxImagesPerMessage: 20,
      maxMessageImageBytes: 100 * 1024 * 1024,
      maxImagePixels: 40_000_000,
      maxImageDimension: 2000,
      mediaTypes: ['image/png', 'image/jpeg', 'image/webp'],
    },
    admitPromptContent: async (content: readonly unknown[]) => [...content],
  })
  live.provide('fileUploads', {
    registerAgentResolver: () => () => {},
    resolve: () => undefined,
    retirePrompt: () => {},
    bindPrompt: () => ({
      commit: () => {},
      [Symbol.dispose]: () => {},
    }),
  })
  live.provide('fs', {})
  live.provide('credentials', {
    resolve: async (ref: unknown) => ref === CREDENTIAL_REF ? { value: resolveCredential() } : undefined,
    readRecord: async () => undefined,
    listRecords: async () => [],
    modifyRecord: async () => {
      throw new Error('in-memory credential seam is read-only')
    },
    deleteRecord: async () => {},
  })

  const persistenceRoot = join(runRoot, 'sessions')
  await live.plugin(JsonlSessionPersistence, { root: persistenceRoot, compression: 'none' })
  installModelSelectionProjection(live)
  new SessionQueryEngine(live)
  await live.plugin(PiAiModule, {
    providers: {
      [PROVIDER]: {
        apiKeyEnv: CREDENTIAL_REF,
        displayName: 'Lawbench synthetic 6000D',
        api: 'openai-completions',
        baseURL: MODEL_URL,
        models: [{
          id: MODEL,
          name: MODEL,
          contextWindow: 32_768,
          maxTokens: MAX_TOKENS,
          input: ['text'],
          reasoningEfforts: false,
        }],
        defaultInput: ['text'],
        defaultContextWindow: 32_768,
        defaultMaxTokens: MAX_TOKENS,
        cacheRetention: 'none',
        transport: 'sse',
        streamIdleTimeoutMs: 300_000,
      },
    },
  })
  await live.plugin(AgentLoop, { agents: [] })

  const agents = new ApiSessionAgentController(live)
  const workspaceRoot = join(runRoot, 'workspace')
  const commands = new SessionCommandController(live, agents, workspaceRoot)
  const reopenPersistedEvents = async (
    sourceSessionId: string,
    childSessionId: string,
  ): Promise<{ readonly source: readonly NativeEvent[]; readonly child: readonly NativeEvent[] }> => {
    const verifier = new Context()
    let source: readonly NativeEvent[] = []
    let child: readonly NativeEvent[] = []
    try {
      await verifier.plugin(LlmRuntime)
      await verifier.plugin(SessionStore)
      await verifier.plugin(SessionProjectionRegistry)
      await verifier.plugin(SystemPrompt, { personaPrefix: '' })
      await verifier.plugin(ToolRuntime)
      await verifier.plugin(AgentRegistry)
      installModelSelectionProjection(verifier)
      await verifier.plugin(JsonlSessionPersistence, { root: persistenceRoot, compression: 'none' })
      await verifier.plugin(AgentLoop, { agents: [] })
      source = await readPersistedEvents(verifier, sourceSessionId)
      child = await readPersistedEvents(verifier, childSessionId)
    } finally {
      await verifier.fiber.dispose()
    }
    return { source, child }
  }
  return {
    live,
    commands,
    BrowserSession,
    SessionLogOffset,
    persistenceRoot,
    workspaceRoot,
    reopenPersistedEvents,
  }
}

async function main(): Promise<void> {
  const options = parseRunOptions(process.argv.slice(2))
  const mode = options.mode
  const runRoot = await createPrivateRunRoot()
  const networkGate: NetworkGateState = {
    preflightOnly: mode === 'preflight-only',
    keyReady: false,
    closedAttempts: 0,
  }
  const environment = isolateProcessFiles(runRoot)
  const cleanupFailures: string[] = []
  let secret = ''
  let secretReader: SecretReaderState | undefined
  let outputRedaction: OutputRedactionLease | undefined
  let fetchLease: FetchLease | undefined
  let clientSessionsDisposed = false
  let fiberDisposed = false
  let environmentRestored = false
  let fetchRestored = false
  let outputRedactionRestored = false
  let keyCleared = false
  let ctx: ProductionContext | undefined
  const browserSessions: { dispose(): Promise<void> }[] = []
  const nativeEvents: NativeEventRecord[] = []
  const network: NetworkObservation[] = []
  const turns: TurnRecord[] = []
  let sourceSessionId: string | undefined
  let childSessionId: string | undefined
  let sourceAtFork: SessionSnapshot | undefined
  let sourceAfterChild: SessionSnapshot | undefined
  let childAfterFork: SessionSnapshot | undefined
  let childAfterTurn: SessionSnapshot | undefined
  let childInheritance: RunReport['childInheritance']
  let persistence: RunReport['persistence']

  const report: RunReport = {
    format: 'lawbench-native-real-conversation-v2',
    task: 'A-native-real-conversation-20261028-000823',
    mode,
    status: 'RUNNING',
    authoredStatus: 'AUTHORED_NOT_RUN',
    process: {
      executable: process.execPath,
      pid: process.pid,
      startedAtUtc: processBirthUtc(),
    runRoot,
    admission: {},
    turns,
    network,
    networkSummary: {
      observations: 0,
      modelPostAttempts: 0,
      modelPostHttp200: 0,
      closedAttempts: 0,
    },
    nativeEvents,
    cleanup: {
      fiberDisposed: false,
      clientSessionsDisposed: false,
      fetchRestored: false,
      outputRedactionRestored: false,
      environmentRestored: false,
      keyCleared: false,
      failures: cleanupFailures,
    },
    claims: {
      fullT31: false,
      gui: false,
      compression: false,
      tools: false,
      packaging: false,
    },
  }

  try {
    report.admission.initial = await verifyFixedInputs()
    fetchLease = installFetchAllowlist(network, networkGate)
    const production = await setupProduction(
      runRoot,
      () => {
        if (secret.length === 0) {
          throw new Error('production requested a credential before interactive TTY readiness')
        }
        return secret
      },
      live => {
        ctx = live
      },
    )
    const live = production.live
    const commands = production.commands
    const workspaceRoot = production.workspaceRoot
    live.on('session/event', (session: { readonly id: string }, event: NativeEvent) => {
      nativeEvents.push({ sessionId: String(session.id), event })
    })

    const created = await withWatchdog(commands.create({ cwd: workspaceRoot })) as {
      readonly sessionId: string
    }
    sourceSessionId = String(created.sessionId)
    report.sourceSessionId = sourceSessionId
    const source = live.sessions.get(created.sessionId)
    const sourceAgent = live.agents.get(created.sessionId) as
      | { readonly whenIdle(): Promise<void> }
      | undefined
    if (source === undefined || sourceAgent === undefined) {
      throw new Error('production SessionController.create did not publish Session and Agent')
    }
    const sourceUuid = SESSION_WITH_UUID.exec(sourceSessionId)?.[1]
    if (sourceUuid === undefined || !UUID_V4.test(sourceUuid)) {
      throw new Error(`production create did not mint an actual UUID identity: ${sourceSessionId}`)
    }

    const sourceBrowser = new production.BrowserSession(source.id, {})
    browserSessions.push(sourceBrowser)
    sourceBrowser.handleRunning(true)

    if (mode === 'preflight-only') {
      report.preflight = {
        setupCompleted: true,
        productionSessionCreated: true,
        keyRead: false,
        promptsSubmitted: 0,
        modelNetworkAttempts: 0,
        fullConversationAssertionsEvaluated: false,
      }
      report.status = 'CLEARSETUP_ONLY'
    } else {

    const credential = options.credentialStdin
      ? await readCredentialFromStdin()
      : await readCredentialFromTty()
    secret = credential.secret
    secretReader = credential.state
    outputRedaction = installOutputRedaction(secret)
    networkGate.keyReady = true

    const isModelPost = (observation: NetworkObservation): boolean => {
      if (observation.method !== 'POST') return false
      return new URL(observation.url).pathname.startsWith('/v1/')
    }

    const promptTurn = async (
      sessionId: string,
      agent: { followup?: never; whenIdle(): Promise<void> },
      browser: BrowserSessionInstance,
      prompt: string,
    ): Promise<TurnRecord> => {
      const nativeSession = live.sessions.get(sessionId)
      if (nativeSession === undefined) throw new Error(`live Session ${sessionId} is unavailable`)
      const beforeSeq = Number(nativeSession.seq)
      const networkStart = network.length
      const submission = browser.beginSubmission({
        mode: 'queue',
        text: prompt,
        attachments: [],
      })
      const requestId = String(submission.requestId)
      if (!UUID_V4.test(requestId)) throw new Error(`beginSubmission did not mint a UUID v4 R: ${requestId}`)
      await withWatchdog(commands.prompt({
        sessionId: nativeSession.id,
        requestId: submission.requestId,
        mode: 'queue',
        content: [{ type: 'text', text: prompt }],
      }))
      await withWatchdog(agent.whenIdle())
      const afterSeq = Number(nativeSession.seq)
      const events = nativeSession.snapshotEvents(
        production.SessionLogOffset(beforeSeq),
        production.SessionLogOffset(afterSeq),
      ) as readonly NativeEvent[]
      const requestHeaderObservation = requestHeaderAtBoundary(
        nativeSession,
        production.SessionLogOffset,
        beforeSeq,
        afterSeq,
        events,
      )
      const base = assertTurn(
        sessionId,
        requestId,
        prompt,
        beforeSeq,
        afterSeq,
        events,
        requestHeaderObservation,
      )
      const turnNetwork = network.slice(networkStart)
      const modelPosts = turnNetwork.filter(isModelPost)
      const record: TurnRecord = {
        ...base,
        networkStart,
        modelPostAttempts: modelPosts.length,
        modelPostHttp200: modelPosts.filter(item => item.status === 200).length,
      }
      if (record.modelPostAttempts === 0 || record.modelPostHttp200 === 0) {
        throw new Error(`turn for request ${requestId} lacked an actual model POST with HTTP 200`)
      }
      turns.push(record)
      return record
    }

    const first = await promptTurn(sourceSessionId, sourceAgent, sourceBrowser, PROMPTS[0])
    assertContainsFacts(first.responseText, ['已记住'], 'turn 1')
    const second = await promptTurn(sourceSessionId, sourceAgent, sourceBrowser, PROMPTS[1])
    assertContainsFacts(second.responseText, [SYNTHETIC_CODE], 'turn 2')
    const third = await promptTurn(sourceSessionId, sourceAgent, sourceBrowser, PROMPTS[2])
    assertContainsFacts(third.responseText, [SYNTHETIC_PERSON, SYNTHETIC_AMOUNT], 'turn 3')
    assertContiguous(source, `source Session ${sourceSessionId}`)
    sourceAtFork = nativeSnapshot(source)

    const forked = await withWatchdog(commands.fork({ sessionId: source.id })) as {
      readonly sessionId: string
    }
    childSessionId = String(forked.sessionId)
    report.childSessionId = childSessionId
    if (childSessionId === sourceSessionId) throw new Error('production fork reused the source Session identity')
    const childUuid = SESSION_WITH_UUID.exec(childSessionId)?.[1]
    if (childUuid === undefined || !UUID_V4.test(childUuid) || childUuid === sourceUuid) {
      throw new Error(`production fork did not mint a distinct UUID identity: ${childSessionId}`)
    }
    const child = live.sessions.get(forked.sessionId)
    const childAgent = live.agents.get(forked.sessionId) as
      | { readonly whenIdle(): Promise<void> }
      | undefined
    if (child === undefined || childAgent === undefined) {
      throw new Error('production fork did not publish the new Session and Agent')
    }
    childAfterFork = nativeSnapshot(child)
    const inherited = childAfterFork.events.slice(0, childAfterFork.inheritedEventCount)
    const sourcePrefix = sourceAtFork.events.slice(0, childAfterFork.inheritedEventCount)
    childInheritance = {
      parentSession: String(child.header.parentSession),
      isSeeded: child.header.isSeeded === true,
      inheritedEventCount: childAfterFork.inheritedEventCount,
      inheritedPrefixEqual: isDeepStrictEqual(inherited, sourcePrefix),
      sourceUnchanged: isDeepStrictEqual(source.snapshotEvents(), sourceAtFork.events),
    }
    if (childInheritance.parentSession !== sourceSessionId) {
      throw new Error(`fork lineage points to ${childInheritance.parentSession}, not ${sourceSessionId}`)
    }
    if (!childInheritance.isSeeded || !childInheritance.inheritedPrefixEqual) {
      throw new Error('fork did not inherit the exact native source prefix')
    }
    if (!childInheritance.sourceUnchanged) throw new Error('fork mutated the source Session')
    if (!child.snapshotEvents().some(event => event.type === 'session/end-seed')) {
      throw new Error('fork lacks the native session/end-seed marker')
    }

    const childBrowser = new production.BrowserSession(child.id, {})
    browserSessions.push(childBrowser)
    childBrowser.handleRunning(true)
    const childTurn = await promptTurn(childSessionId, childAgent, childBrowser, FORK_PROMPT)
    assertContainsFacts(
      childTurn.responseText,
      [SYNTHETIC_CODE, SYNTHETIC_PERSON, SYNTHETIC_AMOUNT],
      'fork follow-up',
    )
    assertContiguous(child, `child Session ${childSessionId}`)
    sourceAfterChild = nativeSnapshot(source)
    childAfterTurn = nativeSnapshot(child)
    if (!isDeepStrictEqual(sourceAfterChild.events, sourceAtFork.events)) {
      throw new Error('child follow-up appended to or changed the source Session')
    }

    await live.fiber.dispose()
    fiberDisposed = true
    ctx = undefined

    const reopened = await production.reopenPersistedEvents(sourceSessionId, childSessionId)
    persistence = {
      root: production.persistenceRoot,
      sourceReopened: reopened.source.length > 0,
      childReopened: reopened.child.length > 0,
      sourceEqual: isDeepStrictEqual(reopened.source, sourceAfterChild.events),
      childEqual: isDeepStrictEqual(reopened.child, childAfterTurn.events),
    }
    if (!persistence.sourceEqual || !persistence.childEqual) {
      throw new Error('reopened JSONL logs do not equal the native live events')
    }
    const modelPosts = network.filter(isModelPost)
    const successfulModelPosts = modelPosts.filter(item => item.status === 200)
    if (modelPosts.length < 4 || successfulModelPosts.length < 4) {
      throw new Error(
        `expected at least four actual model POSTs with HTTP 200, got ${modelPosts.length} POSTs and`
        + ` ${successfulModelPosts.length} HTTP 200 results`,
      )
    }
    if (network.some(item => item.redirect !== 'error')) {
      throw new Error('a model network observation did not enforce redirect denial')
    }
    report.status = 'PASS'
    }
  } catch (error: unknown) {
    report.status = 'FAILED'
    report.error = safeError(error, secret)
  } finally {
    if (sourceAtFork !== undefined) report.sourceAtFork = sourceAtFork
    if (sourceAfterChild !== undefined) report.sourceAfterChild = sourceAfterChild
    else if (ctx !== undefined && sourceSessionId !== undefined) {
      try {
        const source = ctx.sessions.get(sourceSessionId as never)
        if (source !== undefined) report.sourceAfterChild = nativeSnapshot(source)
      } catch (error: unknown) {
        cleanupFailures.push(`final source Session snapshot failed: ${errorName(error)}`)
      }
    }
    if (childAfterFork !== undefined) report.childAfterFork = childAfterFork
    if (childAfterTurn !== undefined) report.childAfterTurn = childAfterTurn
    else if (ctx !== undefined && childSessionId !== undefined) {
      try {
        const child = ctx.sessions.get(childSessionId as never)
        if (child !== undefined) report.childAfterTurn = nativeSnapshot(child)
      } catch (error: unknown) {
        cleanupFailures.push(`final child Session snapshot failed: ${errorName(error)}`)
      }
    }
    if (childInheritance !== undefined) report.childInheritance = childInheritance
    if (persistence !== undefined) report.persistence = persistence

    let browserDisposeFailed = false
    for (const browser of browserSessions.reverse()) {
      try {
        await browser.dispose()
