    B_SERVICE / "lawbench" / "case" / "registry.py":
        "05d3266afd7efb4108d416102c35d548aae29b011cdfb8b757872a8b0e656c21",
    B_SERVICE / "lawbench" / "case" / "gate.py":
        "cfed621cd2729d595c61f600c6eea88903de867d5647911881314104171a482e",
